  if (filePath && !isInsideProject(filePath, n.cwd || process.cwd())) return { block: false };
  const pathHit = TARGET_RE.test(filePath);
  const contentHit = CONTENT_RE.test(content);
  if (!pathHit && !contentHit) return { block: false };

  const why = pathHit ? filePath.match(TARGET_RE)[0] : content.match(CONTENT_RE)[0];
